import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import { t } from './util';

/** "Double XP until Sunday 8 PM" while an event runs (the next one, a day ahead). */
export default class BoostBanner extends Component {
  view() {
    const now = Date.now();
    const boosts = app.forum.attribute('renownBoosts') || [];
    const running = boosts.find(b => Date.parse(b.starts_at) <= now && Date.parse(b.ends_at) > now);
    const soon = !running && boosts.find(b => Date.parse(b.starts_at) > now && Date.parse(b.starts_at) - now < 86400000);
    const boost = running || soon;
    if (!boost) return null;
    const when = iso => new Date(iso).toLocaleString(undefined, {
      weekday: 'long',
      hour: 'numeric',
      minute: '2-digit'
    });
    const tag = boost.tag_id ? app.store.getById('tags', String(boost.tag_id)) : null;
    return m("div", {
      className: 'RenownBoost' + (running ? ' is-running' : '')
    }, m(Icon, {
      name: "fas fa-bolt"
    }), m("span", {
      className: "RenownBoost-text"
    }, m("strong", null, boost.title || t('boost.title_' + boost.multiplier)), ' ', running ? t('boost.until', {
      time: when(boost.ends_at)
    }) : t('boost.starts', {
      time: when(boost.starts_at)
    }), tag ? m('[', null, " \xB7 ", t('boost.in_tag', {
      tag: tag.name()
    })) : null));
  }
}